title: $:/plugins/cdr/markdown-more/markdown-it-admonition.js
type: application/javascript
module-type: library

Adds admonition container:

:::category optional title string
admonition body
:::
\*/

(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

var categories = {
	note: null,
	info: null,
	todo: null,
	important: null,
	tip: null,
	success: null,
	question: null,
	warning: null,
	caution: null,
	fail: null,
	danger: null,
	error: null,
	bug: null,
	example: null,
	snippet: null,
	abstract: null,
	summary: null,
	quote: null,
	cite: null,
	"see-also": "SEE ALSO"
};

// initialize default title string
for(var c in categories) {
	if(!categories[c]) {
		categories[c] = c.toUpperCase();
	}
};

var AdmMarkerCode;

var AdmHeadingRegEx = /^\s*([a-zA-Z-]+[a-zA-Z])([-+]?)(?:\s*$|\s+(.*?)\s*$)/;
function parseHeading(text) {
	var m = text.match(AdmHeadingRegEx);
	if(m) {
		const cat = m[1].toLowerCase();
		// biome-ignore lint/suspicious/noPrototypeBuiltins: safe, hasOwnProperty not shadowed
		if(categories.hasOwnProperty(cat)) {
			return {
				category: cat,
				state: (m[2] || null),
				title: (m[3] || categories[cat])
			};
		}
	}
	return null;
}

// parse through source from startLine until endLine or markup string
function reachBlockEnd(state,startLine,endLine,markup) {
	let nextLine=startLine;
	// biome-ignore lint/style/useSingleVarDeclarator: compact layout
	let pos, mem, max, haveEndMarker=false;

	for(nextLine = startLine; nextLine < endLine; nextLine++) {
		pos = mem = state.bMarks[nextLine] + state.tShift[nextLine];
		max = state.eMarks[nextLine];

		if(pos < max && state.sCount[nextLine] < state.blkIndent) {
			// non-empty line with negative indent should stop the list:
			// - ```
			//  test
			break;
		}

		if(state.src.charCodeAt(pos) !== AdmMarkerCode) { continue; }

		if(state.sCount[nextLine] - state.blkIndent >= 4) {
			// closing fence should be indented less than 4 spaces
			continue;
		}

		pos = state.skipChars(pos,AdmMarkerCode);

		// closing code fence must be at least as long as the opening one
		if(pos - mem < markup.length) { continue; }

		// make sure tail has spaces only
		if(state.skipSpaces(pos) < max) { continue; }

		// found!
		haveEndMarker = true;
		break;
	}

	if(haveEndMarker) {
		nextLine++;
	}

	return { endLine: nextLine, endMarker: (haveEndMarker ? state.src.slice(mem,pos) : "") };
}

module.exports = function admonitionPlugin(md,options) {
	function admonitionRule(state,startLine,endLine,silent) {
		const start = state.bMarks[startLine] + state.tShift[startLine];
		const max = state.eMarks[startLine];

		if(start + 3 > max) { return false; }

		if(state.src.charCodeAt(start) !== AdmMarkerCode) {
		  return false;
		}

		// scan marker length, must be >= 3
		const pos = state.skipChars(start,AdmMarkerCode);

		if(pos - start < 3) { return false; }

		const markup = state.src.slice(start,pos);
		const params = state.src.slice(pos,max);

		// parse heading
		var heading = parseHeading(params);
		if(!heading) { return false; }

		// Since start is found, we can report success here in validation mode
		if(silent) { return true; }

		var loop = reachBlockEnd(state,startLine + 1,endLine,markup);
		var oldParent = state.parentType;
		var oldLineMax = state.lineMax;
		state.parentType = 'admonition';

		var blockTag = heading.state ? 'details' : 'div';
		var titleTag = heading.state ? 'summary' : 'div';

		let token = state.push('admonition_open',blockTag,1);
		token.markup = markup;
		token.block  = true;
		token.info   = heading.category;
		token.map    = [ startLine, loop.endLine ];
		token.attrSet('class','admonition');
		token.attrSet('data-admonition',heading.category);
		if(heading.state === '+') {
			token.attrSet('open','open');
		}

		// shows title bar only if content is not ''
		if(heading.state || heading.title !== "''") {
			// admonition title
			token = state.push('admonition_title_open',titleTag,1);
			token.markup = markup;
			token.info   = heading.category;
			token.map    = [ startLine, startLine + 1 ];
			token.attrSet('class','admonition-title');

			token = state.push('inline','',0);
			token.content  = (heading.title === "''" ? '' : heading.title);
			token.map      = [ startLine, startLine + 1 ];
			token.children = [];

			token = state.push('admonition_title_close',titleTag,-1);
			token.markup = markup;
			token.info   = heading.category;
		}

		token = state.push('admonition_body_open','div',1);
		token.attrSet('class','admonition-body');
		token.map = [ startLine + 1, loop.endLine - (loop.endMarker ? 1 : 0) ];

		// this will prevent lazy continuations from ever going past our end marker
		state.lineMax = token.map[1];
		state.md.block.tokenize(state,token.map[0],token.map[1]);

		token  = state.push('admonition_body_close','div',-1);
		token  = state.push('admonition_close',blockTag,-1);
		token.markup = loop.endMarker;
		token.block  = true;

		state.parentType = oldParent;
		state.lineMax = oldLineMax;
		state.line = loop.endLine;

		return true;
	}

	//var defaults = { marker: ":" };

	options = options || {};

	AdmMarkerCode = (options.maker || ":").charCodeAt(0);

	//options = md.utils.assign({},defaults,options);
	//options.markerCode = options.marker.charCodeAt(0);

	md.block.ruler.before('fence','admonition',admonitionRule,{
		alt: [ 'paragraph', 'reference', 'blockquote', 'list' ]
	});
};
})();","type":"application/javascript","module-type":"library"},"$:/plugins/cdr/markdown-more/markdown-it-checklist.js":{"title":"$:/plugins/cdr/markdown-more/markdown-it-checklist.js","text":"/*\
title: $:/plugins/cdr/markdown-more/markdown-it-checklist.js
type: application/javascript
module-type: library

Adds checklist syntax:

```
- [ ] task 1
- [x] task 2
```
\*/
(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

var CheckBoxRegEx = /^\[([xX ])\]\s+/g;

// token[idx] is the first inline token of a list item
function processListItemStart(state,tokens,idx) {
	var tok = tokens[idx]; // inline token
	var blockState = state.md.blockState;

	if(tok.children.length <= 0) { return; }

	var text = tok.children[0].content;

	CheckBoxRegEx.lastIndex = 0;
	var match = CheckBoxRegEx.exec(text);

	if(match) {
		var checked = false;
		if(match[1] === " ") {
			tokens[idx - 2].attrSet("class","checklist-item unchecked");
		} else {
			tokens[idx - 2].attrSet("class","checklist-item checked");
			checked = true;
		}
		tok.children[0].content = text.substring(CheckBoxRegEx.lastIndex);
		var inputToken = new state.Token('checkbox','$md-checkbox',0);
		inputToken.attrSet("class","checklist-item-checkbox");
		inputToken.attrSet("type","checkbox");
		inputToken.attrSet("pos",blockState.bMarks[tokens[idx].map[0]]);
		if(checked) {
			inputToken.attrSet("checked","");
		}
		tok.children.unshift(inputToken);
	}
}

function isListItemStart(tokens,idx) {
	return tokens[idx].type === "inline" &&
		tokens[idx - 1].type == "paragraph_open" &&
		tokens[idx - 2].type === "list_item_open";
}

function processLists(state) {
	var tokens = state.tokens;

	for(var idx = 2; idx < tokens.length; idx++) {
		if(isListItemStart(tokens,idx)) {
			processListItemStart(state,tokens,idx);
		}
	}
	delete state.md.blockState;
}

function checklistPlugin(md,options) {
	md.core.ruler.after('inline','checklist',processLists,options);

	// insert a dummy rule in order to preserve block processing's state object
	md.block.ruler.before('table','_dummy_',function(state,startLine,endLine,silent) {
		state.md.blockState = state;
		return false;
	});
}

module.exports = checklistPlugin;
})();","type":"application/javascript","module-type":"library"},"$:/plugins/cdr/markdown-more/markdown-it-example.js":{"title":"$:/plugins/cdr/markdown-more/markdown-it-example.js","text":"/*\
title: $:/plugins/cdr/markdown-more/markdown-it-example.js
type: application/javascript
module-type: library

Adds example syntax:

```
-> example sentence  // comment
```
\*/

(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

function examplePlugin(md,options) {
	function exampleRule(state,startLine,endLine,silent) {
		var token, ch,
		markup = '->',
		pos = state.bMarks[startLine] + state.tShift[startLine],
		max = state.eMarks[startLine];

  		// if it's indented more than 3 spaces, it should be a code block
  		if(state.sCount[startLine] - state.blkIndent >= 4) { return false; }

		if(pos+1 >= max) { return false; }

		if(state.src.charCodeAt(pos++) !== markup.charCodeAt(0)) { return false; }

		if(state.src.charCodeAt(pos++) !== markup.charCodeAt(1)) { return false; }

		if(pos < max) {
			ch = state.src.charCodeAt(pos);
			if(ch !== 0x09 /* TAB */ && ch !== 0x20 /* space */) { return false; }
		}

		if(silent) {
			return true;
		}

		var terminatorRules = state.md.block.ruler.getRules('paragraph');
		var oldParentType = state.parentType;
		state.parentType = 'paragraph';

		// jump line-by-line until empty one or EOF
		var nextLine = startLine + 1;
		for(; nextLine < endLine && !state.isEmpty(nextLine); nextLine++) {
			// this would be a code block normally, but after paragraph
   	 		// it's considered a lazy continuation regardless of what's there
    		if(state.sCount[nextLine] - state.blkIndent > 3) { continue; }

			// quirk for blockquotes, this line should already be checked by that rule
    		if(state.sCount[nextLine] < 0) { continue; }

			// Some tags can terminate paragraph without empty line.
			let terminate = false;
			for (let i = 0;i < terminatorRules.length;i++) {
				if (terminatorRules[i](state, nextLine, endLine, true)) {
					terminate = true;
					break;
				}
			}
			if (terminate) { break; } 
		}

		var content = state.src.slice(pos + 1,state.eMarks[startLine] + 1) + state.getLines(startLine + 1, nextLine, state.blkIndent, false);
		var comment = null;
		var i = content.indexOf('//');
		if(i != -1) {
			comment = content.slice(i+2).trim();
			content = content.slice(0,i).trim();
		}

		state.line = nextLine;
		state.parentType = oldParentType;

		token = state.push('example_open','div',1);
		token.attrSet('class','md-example-container');
		token.block  = true;
		token.markup = markup;
		token.map = [ startLine, state.line ];

		token = state.push('example_text_open','span',1);
		token.attrSet('class','md-example-text');
		token.map = [ startLine, nextLine ];

		token = state.push('inline','',0);
  		token.content  = content;
  		token.map      = [ startLine, state.line ];
  		token.children = [];

		token = state.push('example_text_close','span',-1);

		if(comment) {
			token = state.push('example_comment_open','span',1);
			token.attrSet('class','md-example-comment');
			token.map = [ startLine, state.line ];

			token = state.push('inline','',0);
			token.content  = comment;
			token.map      = [ startLine, state.line ];
			token.children = [];

			token = state.push('example_comment_close','span',-1);		
		}

		token = state.push('example_close','div',-1);
		token.block  = true;
		token.markup = markup;

		return true;
	}

	md.block.ruler.after('heading','example',exampleRule,{
		alt: [ 'paragraph', 'reference', 'blockquote' ]
	});
}

module.exports = examplePlugin;
})();","type":"application/javascript","module-type":"library"},"$:/plugins/cdr/markdown-more/markdown-it-twtable.js":{"title":"$:/plugins/cdr/markdown-more/markdown-it-twtable.js","text":"/*\
title: $:/plugins/cdr/markdown-more/markdown-it-twtable.js
type: application/javascript
module-type: library

Based on markdown-it-table https://github.com/markdown-it/markdown-it/ | MIT License

Extends markdown-it to parse WikiText style tables
\*/

(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
'use strict';

function getLine(state,line) {
	const pos = state.bMarks[line] + state.tShift[line];
	const max = state.eMarks[line];

	return state.src.slice(pos,max);
}


/**
 * Returns an array of columns; last item in the returned array contains the row modifier info or '' if none.
 * Returns null if `str` is not a valid WikiText table row.
 *
 * @returns {string[] | null}
 */
function escapedSplit(str) {
	const result = [];
	const max = str.length;

	let isEscaped = false;
	let current = '';

	// minimum requirement for a table: `||`
	if(max < 2) { return null; }

	if(str.charCodeAt(0) !== 0x7c/* | */) { return null; }

	let pos = 1;
	let ch = str.charCodeAt(pos);
	let lastPos = pos;

	while(pos < max) {
		if(ch === 0x7c/* | */) {
			if(!isEscaped) {
				// pipe separating cells: '|'
				result.push(current + str.substring(lastPos,pos));
				current = '';
				lastPos = pos + 1;
			} else {
				// escaped pipe: '\|'
				current += str.substring(lastPos,pos - 1);
				lastPos = pos;
			}
		}

		isEscaped = (ch === 0x5c/* \ */);
		pos++;

		ch = str.charCodeAt(pos);
	}

	result.push(current + str.substring(lastPos));

	if(result.length < 2) { return null; }

	current = result[result.length - 1];

	const validTypes = 'fhckgw';

	if(current.length > 1 || ! validTypes.includes(current)) { return null; }

	return result;
}

/**
 * @param {TblCell[]} columns
 */
function pushColumnsIntoState(state,lineno,columns) {
	let token = state.push('tr_open','tr',1);
	token.map = [lineno, lineno + 1];

	for(let i = 0; i < columns.length; i++) {
		const cell = columns[i];
		if(cell.inline === null) {
			continue;
		}

		token = state.push(`${cell.tag}_open`,cell.tag,1);
		if(cell.style) {
			token.attrSet('style',cell.style);
		}
		if(cell.colspan > 1) {
			token.attrSet('colspan',cell.colspan);
		}
		if(cell.rowspan > 1) {
			token.attrSet('rowspan',cell.rowspan);
		}
		cell.token = token;

		token = state.push('inline','',0);
		token.content = cell.inline;
		token.children = [];

		state.push(`${cell.tag}_close`,cell.tag,-1);
	}
	state.push('tr_close','tr',-1);
}

/**
 * @param {string[]} columns
 *
 * @returns {ColGrpCell[]}
 */
function processColgroup(columns) {
	const row = [];
	let pendingColSpan = 0;

	for(let i=0; i < columns.length; i++) {
		const col = columns[i];
		/** @type { ColGrpCell } */
		const cell = {
			span: 1,
			content: null
		};

		if(col === '<') {
			pendingColSpan = 0;
			for(let c = row.length - 1; c >= 0; c--) {
				if(row[c] && row[c].content !== null) {
					row[c].span++;
					break;
				}
			}
		} else if(col === '>') {
			pendingColSpan++;
		} else {
			cell.content = col.trim();

			if(pendingColSpan > 0) {
				cell.span += pendingColSpan;
				pendingColSpan = 0;
			}
		}

		row.push(cell);
	}
	return row;
}

/**
 * @param {string[]} columns
 * @param {TblCell[][]} rows
 *
 * @return {TblCell[]}
 */
function processColumns(ishead,columns,rows) {
	let pendingColSpan = 0;
	const row = [];

	for(let i=0; i < columns.length; i++) {
		const col = columns[i];
		/** @type {TblCell} */
		const cell = {
			tag: (ishead ? 'th' : 'td'),
			style: '',
			colspan: 1,
			rowspan: 1,
			inline: null,
			token: null
		};
		let pos = 0;
		let max = col.length;
		let valign;
		let align;
		let style = '';

		if(col === '~') {
			pendingColSpan = 0;
			for(let r = rows.length - 1; r >= 0; r--) {
				const c = rows[r][i];

				if(c && c.inline !== null) {
					c.rowspan++;

					// previous rows may not have been pushed
					if(c.token !== null) {
						c.token.attrSet('rowspan',c.rowspan);
					}
					break;
				}
			}
		} else if(col === '<') {
			pendingColSpan = 0;
			for(let c = row.length - 1; c >= 0; c--) {
				if(row[c] && row[c].inline !== null) {
					row[c].colspan++;
					break;
				}
			}
		} else if(col === '>') {
			pendingColSpan++;
		} else {
			if(pos < max && col.charCodeAt(pos) === 0x5e/* ^ */) {
				valign = 'top';
				pos++;
			}
			if(pos < max && col.charCodeAt(pos) === 0x2c/* , */) {
				valign = 'bottom';
				pos++;
			}
			if(pos < max && col.charCodeAt(pos) === 0x20/* (space) */) {
				align = 'right';
				pos++;
				for(; pos < max; pos++) {
					if(col.charCodeAt(pos) !== 0x20/* (space) */) {
						break;
					}
				}
			}
			if(max - 1 >= pos && col.charCodeAt(max - 1) === 0x20 /* (space) */) {
				align = (align ? 'center' : 'left');
				max--;
			}
			if(pos < max && col.charCodeAt(pos) === 0x21/* ! */) {
				if(cell.tag === 'td') {
					cell.tag = 'th';
					if(! align) {
						align = 'left';
					}
				}
				pos++;
			}

			cell.inline = col.substring(pos,max).trim();
			if(align) {
				style += `text-align:${align};`;
			}
			if(valign) {
				style += `vertical-align:${valign};`;
			}
			cell.style = style;

			if(pendingColSpan > 0) {
				cell.colspan += pendingColSpan;
				pendingColSpan = 0;
			}
		}
		row.push(cell);
	}
	rows.push(row);
	return row;
}

/**
 * @param {StateBlock} state
 * @param {string[]} columns
 * @param {Table} table
 */
function processRow(state,lineno,columns,table) {
	const rowType = columns[columns.length - 1];
	columns.pop();

	let row;
	switch(rowType) {
		case 'h':
			if(table.secToken) {
				if(table.secToken.tag === 'tbody') {
					// @ts-expect-error: map initialized when token is created
					table.secToken.map[1] = lineno;

					// begin a new tbody tag
					state.push('tbody_close','tbody',-1);
					table.secToken = state.push('tbody_open','tbody',1);
					table.secToken.map = [lineno, 0];
					table.rows = [];
				}
			} else {
				// open thead tag
				table.secToken = state.push('thead_open','thead',1);
				table.secToken.map = [lineno, 0];
				table.rows = [];
			}
			row = processColumns(true,columns,table.rows);
			pushColumnsIntoState(state,lineno,row);
			break;
		case 'f':
			row = processColumns(false,columns,table.footer.rows);
			table.footer.maps.push(lineno);
			break;
		case 'c':
			{
				const text = columns.join('|').trim();
				if(table.caption.inlineToken.content === '') {
					table.caption.inlineToken.content = text;
				} else {
					table.caption.inlineToken.content += `<p>${text}</p>`;
				}
			}
			table.caption.openToken.hidden = false;
			table.caption.closeToken.hidden = false;
			break;
		case 'k':
			table.tblToken.attrJoin('class',columns.join(' ').trim());
			break;
		case 'g':
		case 'w':
			if(table.colgrpIdx > 0) {
				const colgroup = processColgroup(columns);
				if(colgroup.length > 0) {
					const groups = [];
					for(let i=0; i < colgroup.length; i++) {
						const c = colgroup[i];

						if(c.content === null) {
							continue;
						}
						const openToken = new state.Token('colgroup_open','colgroup',1);
						const closeToken = new state.Token('colgroup_close','colgroup',-1);

						if(c.span > 1) {
							openToken.attrSet('span',c.span);
						}
						if(c.content !== '') {
							switch (rowType) {
								case "g":
									openToken.attrSet('class',c.content);
									break;
								case "w":
									openToken.attrSet('style',`width:${c.content}`);
									break;
								default:
									break; // shouldn't be reached...
							}
						}

						groups.push(openToken);
						groups.push(closeToken);
					}
					state.tokens.splice(table.colgrpIdx,0,...groups);
				}
				// ignore additional colgroup rows
				table.colgrpIdx = -1
			}
			break;
		default:
			if(table.secToken) {
				if(table.secToken.tag === 'thead') {
					// open a new tbody tag
					// @ts-expect-error: map initialized when token is created
					table.secToken.map[1] = lineno;
					state.push('thead_close','thead',-1);
					table.secToken = state.push('tbody_open','tbody',1);
					table.secToken.map = [lineno, 0];
					table.rows = [];
				}
			} else {
				// open tbody tag
				table.secToken = state.push('tbody_open','tbody',1);
				table.secToken.map = [lineno, 0];
				table.rows = [];
			}
			row = processColumns(false,columns,table.rows);
			pushColumnsIntoState(state,lineno,row);
	}
}

/**
 * - any <thead> not at the top of table are converted to <tbody>
 * - multiple caption tags are merged into one separated by <br>
 * - all tfoot are moved to the end of the table
 *
 * @param {StateBlock} state
 *
 * @returns {boolean}
 */
function twtableRule(state,startLine,endLine,silent) {
	const pos = state.bMarks[startLine] + state.tShift[startLine];

	// if it's indented more than 3 spaces, it should be a code block
	if(state.sCount[startLine] - state.blkIndent >= 4) { return false; }

	if(state.src.charCodeAt(pos) !== 0x7c/* | */) { return false; }

	let lineText = getLine(state,startLine).trim();

	let columns = escapedSplit(lineText);

	if(! columns) { return false; }

	if(silent) {
		return true;
	}

	const oldParentType = state.parentType;
	state.parentType = 'table';

	// use 'blockquote' lists for termination because it's
	// the most similar to tables
	const terminatorRules = state.md.block.ruler.getRules('blockquote');


	const tblToken = state.push('table_open','table',1);
	tblToken.map = [startLine, 0];

	const captionOpenToken = state.push('caption_open','caption',1);
	captionOpenToken.hidden = true;

	const captionInlineToken = state.push('inline','',0);
	captionInlineToken.content = '';
	captionInlineToken.children = [];

	const captionCloseToken = state.push('caption_close','caption',-1);
	captionCloseToken.hidden = true;

	/** @type {Table} */
 	const table = {
		tblToken: tblToken,
		colgrpIdx: state.tokens.length, // token position for colgroup
		caption: { openToken: captionOpenToken, inlineToken: captionInlineToken, closeToken: captionCloseToken },
		secToken: null, // <tbody> or <thead> token
		rows: [], // content of processed rows
		footer: { rows: [], maps: [] },
	};

	processRow(state,startLine,columns,table);

	let nextLine;
	for(nextLine = startLine + 1; nextLine < endLine; nextLine++) {
		if(state.sCount[nextLine] < state.blkIndent) { break }

		let terminate = false;
		for(let i = 0, l = terminatorRules.length; i < l; i++) {
			if(terminatorRules[i](state,nextLine,endLine,true)) {
				terminate = true;
				break;
			}
		}
		if(terminate) { break }

		lineText = getLine(state,nextLine).trim();
		columns = escapedSplit(lineText);

		if(! columns) { break }
		if(!lineText) { break }
		if(state.sCount[nextLine] - state.blkIndent >= 4) { break }

		columns = escapedSplit(lineText)

		if(! columns) { break }
		processRow(state,nextLine,columns,table);
	}

	if(table.secToken) {
		// @ts-expect-error: map initialized when token is created
		table.secToken.map[1] = nextLine;
		state.push(`${table.secToken.tag}_close`,table.secToken.tag,-1);
	}

	if(table.footer.rows.length > 0) {
		const footToken = state.push('tfoot_open','tfoot',1);
		const footer = table.footer;

		let i = 0;
		for(; i < footer.rows.length; i++) {
			pushColumnsIntoState(state,footer.maps[i],footer.rows[i]);
		}
		state.push('tfoot_close','tfoot',-1);
		footToken.map = [footer.maps[0], footer.maps[i-1]];
	}

	state.push('table_close','table',-1);
	tblToken.map[1] = nextLine;

	state.parentType = oldParentType;
	state.line = nextLine;
	return true;
}

function twtablePlugin(md,options) {
	md.block.ruler.after('table','twtable',twtableRule,{
		alt: [ 'paragraph', 'reference' ]
	});
}

module.exports = twtablePlugin;
